// Parses Gemini's JSON output and merges it back with the original source item
const source = $('Loop Over Sources').item.json;

let parsed = { important: false };
try {
  const raw = $json.candidates[0].content.parts[0].text;
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { important: false, parse_error: String(e) };
}

const title = parsed.title || source.name;
const dedupeKey = `${title}|${source.url}`;
const isDuplicate = (source.existingKeys || []).includes(dedupeKey);

return [{
  json: {
    source_name: source.name,
    source_category: source.category,
    source_url: source.url,
    important: parsed.important === true,
    type: parsed.type || 'Unknown',
    title: title,
    deadline: parsed.deadline || 'Not specified',
    summary: parsed.summary || '',
    score: parsed.score || source.ai_score || 5,
    dedupeKey,
    isDuplicate
  }
}];
